targets.expr:
avg(
  1000 * sum by(pod) (
    rate(
      container_cpu_usage_seconds_total{
        namespace="$namespace", 
        k8scluster="$cluster",
        container="",
        pod=~"$Application-[A-Za-z0-9]+-[A-Za-z0-9]+"
      }[1m]
    )
  ) 
  / sum by(pod) (
    kube_pod_container_resource_requests{
      namespace="$namespace", 
      pod=~"$Application-[A-Za-z0-9]+-[A-Za-z0-9]+", 
      resource="cpu"
    } * 1000
  )
) * 100

